package io.invenlio.warehouse;
import java.util.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;
interface WarehouseRepository extends JpaRepository<Warehouse,UUID>,JpaSpecificationExecutor<Warehouse>{Optional<Warehouse>findByIdAndTenantId(UUID id,UUID tenant);boolean existsByTenantIdAndNormalizedCode(UUID tenant,String code);}
interface ZoneRepository extends JpaRepository<WarehouseZone,UUID>,JpaSpecificationExecutor<WarehouseZone>{Optional<WarehouseZone>findByIdAndTenantId(UUID id,UUID tenant);Optional<WarehouseZone>findByIdAndTenantIdAndWarehouseId(UUID id,UUID tenant,UUID warehouse);boolean existsByTenantIdAndWarehouseIdAndNormalizedCode(UUID tenant,UUID warehouse,String code);}
interface LocationRepository extends JpaRepository<StorageLocation,UUID>,JpaSpecificationExecutor<StorageLocation>{Optional<StorageLocation>findByIdAndTenantId(UUID id,UUID tenant);Optional<StorageLocation>findByIdAndTenantIdAndWarehouseId(UUID id,UUID tenant,UUID warehouse);Optional<StorageLocation>findByTenantIdAndNormalizedScanCode(UUID tenant,String scan);boolean existsByTenantIdAndNormalizedScanCode(UUID tenant,String scan);boolean existsByTenantIdAndWarehouseIdAndNormalizedCode(UUID tenant,UUID warehouse,String code);List<StorageLocation>findAllByTenantIdAndWarehouseIdOrderBySequenceAscCodeAsc(UUID tenant,UUID warehouse);boolean existsByTenantIdAndWarehouseIdAndParentIdAndStatusNot(UUID tenant,UUID warehouse,UUID parent,StorageLocation.Status status);boolean existsByTenantIdAndWarehouseIdAndZoneIdAndStatusNot(UUID tenant,UUID warehouse,UUID zone,StorageLocation.Status status);}
